import pandas as pd
import difflib

def clean(df):
    df = df.copy()
    allowed_categories = ["Electronics", "Accessories", "Furniture", "Office Supplies"]
    allowed_regions = ["North", "South", "East", "West"]
    category_typos = {
        "accesories": "Accessories",
        "electornics": "Electronics",
        "office suplies": "Office Supplies",
    }

    def canonicalize(value, allowed, typo_map=None):
        if pd.isna(value):
            return value
        s = " ".join(str(value).split())
        for item in allowed:
            if s.casefold() == item.casefold():
                return item
        if typo_map is not None:
            mapped = typo_map.get(s.casefold())
            if mapped is not None:
                return mapped
        matches = difflib.get_close_matches(s, allowed, n=1, cutoff=0.75)
        return matches[0] if matches else s

    df["Category"] = df["Category"].map(
        lambda x: canonicalize(x, allowed_categories, category_typos)
    )
    df["Region"] = df["Region"].map(
        lambda x: canonicalize(x, allowed_regions)
    )

    df["Quantity"] = pd.to_numeric(df["Quantity"], errors="coerce")
    df["Price"] = pd.to_numeric(df["Price"], errors="coerce")
    df["Revenue"] = df["Quantity"] * df["Price"]
    return df

def answer(df):
    cleaned = clean(df)
    grouped = cleaned.groupby("Category", dropna=True)["Revenue"].sum()
    result = {}
    for key, value in grouped.items():
        if pd.isna(key):
            continue
        number = value
        if float(number).is_integer():
            number = int(number)
        result[str(key)] = number
    return {k: result[k] for k in sorted(result)}
